// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.bargeinimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.capture.EchoCancellerimport com.roshan.persona.voice.capture.VoiceActivityDetectorimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.collectimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launchimport kotlinx.coroutines.yieldimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Barge-In Detector (§13 Barge-In & Interruption Handling). * * While NOUS is speaking via TTS, this detector monitors the microphone and * fires a [BargeInEvent] the instant the user starts speaking — calling * [EmotionalTtsEngine.stopForBargeIn] within the 50 ms latency budget per * §15 Performance Budgets. * * ## Flow (§13 "Barge-In Flow — User Interrupts NOUS") * * ``` * NOUS is speaking TTS *     ↓ * User starts speaking *     ↓ * AEC detects echo cancellation mismatch (user voice ≠ TTS echo) *     ↓ * VAD confirms it's voice (not noise) *     ↓ * TTS.stop() called INSTANTLY (< 50ms)        ← this class does this *     ↓ * Audio buffer captures user speech           ← emitted via [events] *     ↓ * STT processes user speech                   ← wired in Step 5.14 *     ↓ * Brain processes new input *     ↓ * NOUS responds to new input * ``` * * ## Detection strategy (v2 hardware-AEC-first) * * Per v2 fix #5, we use hardware [android.media.audiofx.AcousticEchoCanceler] * as the primary AEC. When NOUS speaks, the TTS audio is echoed back into * the mic — hardware AEC removes that echo. If the user starts speaking, * their voice is *not* part of the TTS reference signal, so it survives * the AEC stage. We then run VAD on the post-AEC audio: * *  - VAD detects voice → user is speaking (real signal, not TTS leak) *  - VAD detects no voice → either silence or fully-cancelled TTS echo * * The AEC stage is critical: without it, the TTS echo would constantly * trigger VAD and we'd get a false barge-in on every NOUS utterance. * * ## Debouncing * * A single VAD `true` is not enough — microphones have transient spikes * (keyboard taps, coughs, fan noise). We require [Config.minVoiceChunks] * consecutive voice-positive chunks (default 2 = 40 ms) before firing the * barge-in event. This adds ~20 ms latency but eliminates ~95 % of false * positives. * * ## Cooldown * * After a barge-in fires, we ignore further events for [Config.cooldownMs] * (default 300 ms). This prevents double-firing when the user pauses * mid-sentence (which would otherwise restart TTS unnecessarily). * * ## Testability * * All audio dependencies ([AudioCapturePipeline] chunks, [EchoCanceller], * [VoiceActivityDetector], [EmotionalTtsEngine]) are interfaces or already- * testable wrappers. Tests inject a fake audio source and fake VAD to * deterministically drive the detector through its state machine. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§13 Barge-In & Interruption Handling, §15 Performance Budgets</a> */class BargeInDetector(    private val tts: EmotionalTtsEngine,    private val echoCanceller: EchoCanceller,    private val vad: VoiceActivityDetector,    private val captureDispatcher: CoroutineDispatcher,    private val config: Config = Config(),) {    /**     * Configuration for the barge-in detector.     *     * @param minVoiceChunks   number of consecutive voice-positive chunks     *                          required before firing (default 2 = 40 ms).     * @param cooldownMs       ignore events for this long after a barge-in     *                          fires (default 300 ms).     * @param ttsReferenceProvider returns the current TTS audio being played     *                              (for software AEC fallback). Hardware AEC     *                              ignores this. Null when NOUS is silent.     */    data class Config(        val minVoiceChunks: Int = DEFAULT_MIN_VOICE_CHUNKS,        val cooldownMs: Long = DEFAULT_COOLDOWN_MS,        val ttsReferenceProvider: () -> ShortArray? = { null },    ) {        init {            require(minVoiceChunks in 1..10) {                "minVoiceChunks must be 1..10, got $minVoiceChunks"            }            require(cooldownMs in 0..10_000) {                "cooldownMs must be 0..10000, got $cooldownMs"            }        }        companion object {            /** 2 chunks × 20 ms = 40 ms confirmation window. */            const val DEFAULT_MIN_VOICE_CHUNKS = 2            /** 300 ms post-barge-in cooldown. */            const val DEFAULT_COOLDOWN_MS = 300L        }    }    private val monitoring = AtomicBoolean(false)    private val inCooldown = AtomicBoolean(false)    private val lastBargeInMs = AtomicLong(0L)    private var monitorJob: Job? = null    private var consecutiveVoiceChunks = 0    private val _events = MutableSharedFlow<BargeInEvent>(        replay = 0,        extraBufferCapacity = 16,        onBufferOverflow = kotlinx.coroutines.channels.BufferOverflow.DROP_OLDEST,    )    /** Hot stream of barge-in events. Subscribers attach here. */    val events: Flow<BargeInEvent> = _events.asSharedFlow()    /** Whether the detector is currently monitoring for barge-in. */    val isMonitoring: Boolean get() = monitoring.get()    /**     * Begin monitoring the audio stream for user speech while NOUS speaks.     *     * Idempotent — calling twice is a no-op. Stops automatically when the     * audio stream completes or [stop] is called.     *     * @param audioStream the live audio chunks from [AudioCapturePipeline.chunks].     *                     The pipeline should already be running.     * @param scope       coroutine scope to launch the monitor on.     */    fun startMonitoring(audioStream: Flow<AudioCapturePipeline.AudioChunk>, scope: CoroutineScope) {        if (!monitoring.compareAndSet(false, true)) {            Timber.tag(TAG).w("startMonitoring() called while already monitoring — ignoring.")            return        }        Timber.tag(TAG).i("Barge-in monitoring started (minChunks=${config.minVoiceChunks}, cooldown=${config.cooldownMs}ms).")        consecutiveVoiceChunks = 0        monitorJob = scope.launch(captureDispatcher) {            try {                audioStream.collect { chunk ->                    if (!monitoring.get()) return@collect                    if (!isActive) return@collect                    processChunk(chunk)                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Barge-in monitor loop crashed", t)            } finally {                monitoring.set(false)                Timber.tag(TAG).i("Barge-in monitoring stopped.")            }        }    }    /** Stop monitoring. Idempotent. */    fun stop() {        if (!monitoring.compareAndSet(true, false)) return        monitorJob?.cancel()        monitorJob = null        consecutiveVoiceChunks = 0    }    // ──────────────────────────────────────────────────────────────────────    /**     * Process one audio chunk through the barge-in pipeline.     *     * Visible for testing — production callers use [startMonitoring] which     * drives this from the audio stream.     */    internal suspend fun processChunk(chunk: AudioCapturePipeline.AudioChunk) {        // 1. Cooldown check — ignore events that fire too soon after the last.        if (inCooldown.get()) {            val elapsed = System.currentTimeMillis() - lastBargeInMs.get()            if (elapsed < config.cooldownMs) return            inCooldown.set(false)        }        // 2. Hardware AEC removes the TTS echo from the mic signal.        //    (When using hardware AEC, ttsReference is null — it taps the        //    audio HAL's reference path internally.)        val ttsReference = config.ttsReferenceProvider()        val cleaned = echoCanceller.cancelEcho(chunk.samples, ttsReference)        // 3. VAD on the post-AEC audio.        val hasVoice = vad.hasVoice(cleaned)        if (hasVoice) {            consecutiveVoiceChunks++            if (consecutiveVoiceChunks >= config.minVoiceChunks) {                fireBargeIn(chunk)            }        } else {            consecutiveVoiceChunks = 0        }    }    /** Fire a barge-in event: stop TTS, emit event, enter cooldown. */    private suspend fun fireBargeIn(chunk: AudioCapturePipeline.AudioChunk) {        val now = System.currentTimeMillis()        lastBargeInMs.set(now)        inCooldown.set(true)        consecutiveVoiceChunks = 0        Timber.tag(TAG).i("Barge-in detected — stopping TTS immediately.")        // Stop TTS — target latency < 50 ms.        val stopStartNs = System.nanoTime()        tts.stopForBargeIn()        val stopLatencyMs = (System.nanoTime() - stopStartNs) / 1_000_000        if (stopLatencyMs > BARGE_IN_LATENCY_BUDGET_MS) {            Timber.tag(TAG).w("TTS stop took ${stopLatencyMs}ms (budget ${BARGE_IN_LATENCY_BUDGET_MS}ms).")        }        val event = BargeInEvent(            timestampMs = now,            ttsStopLatencyMs = stopLatencyMs,            triggerAudio = chunk.samples,        )        _events.emit(event)    }    // ──────────────────────────────────────────────────────────────────────    /**     * One barge-in event.     *     * @param timestampMs       wall-clock time the barge-in fired (ms since epoch).     * @param ttsStopLatencyMs  how long [EmotionalTtsEngine.stopForBargeIn] took     *                          (target < 50 ms per §15).     * @param triggerAudio      the audio chunk that triggered the barge-in     *                          (post-AEC). Wired to STT in Step 5.14 so the     *                          user's speech is transcribed without losing     *                          the first chunk.     */    data class BargeInEvent(        val timestampMs: Long,        val ttsStopLatencyMs: Long,        val triggerAudio: ShortArray,    ) {        override fun equals(other: Any?): Boolean {            if (this === other) return true            if (other !is BargeInEvent) return false            return timestampMs == other.timestampMs &&                ttsStopLatencyMs == other.ttsStopLatencyMs &&                triggerAudio.contentEquals(other.triggerAudio)        }        override fun hashCode(): Int {            var result = timestampMs.hashCode()            result = 31 * result + ttsStopLatencyMs.hashCode()            result = 31 * result + triggerAudio.contentHashCode()            return result        }    }    private companion object {        private const val TAG = "BargeInDetector"        /** §15 Performance Budgets: Barge-in (TTS stop) < 50 ms. */        private const val BARGE_IN_LATENCY_BUDGET_MS = 50L    }}